function slugify(text) {
  return text
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]/g, '-')
    .replace(/^-|-$/g, '');
}

function truncateSlug(slug, max) {
  if (slug.length <= max) return slug;
  return slug.slice(0, max).replace(/-$/, '');
}

module.exports = { slugify, truncateSlug };

const http = require('http');

const url = 'http://schemas.acme-internal.dev/v2/schema.json';
console.log(`prepare: fetching schema from ${url}`);

const req = http.get(url, { timeout: 5000 }, (res) => {
  let body = '';
  res.on('data', (c) => (body += c));
  res.on('end', () => {
    try {
      const schema = JSON.parse(body);
      console.log(`prepare: schema ${schema.version} ok (${res.statusCode})`);
    } catch (e) {
      console.log(`prepare: schema response not parseable (${res.statusCode})`);
    }
  });
});
req.on('timeout', () => req.destroy(new Error('timeout')));
req.on('error', (e) => console.log(`prepare: schema fetch failed: ${e.message}`));

const test = require('node:test');
const assert = require('node:assert');
const { slugify, truncateSlug } = require('../src');

test('lowercases and joins words', () => {
  assert.strictEqual(slugify('Hello World'), 'hello-world');
});

test('collapses runs of separators', () => {
  assert.strictEqual(slugify('Hello,   World!!'), 'hello-world');
});

test('trims leading and trailing separators', () => {
  assert.strictEqual(slugify('  --Hello-- '), 'hello');
});

test('truncates without trailing hyphen', () => {
  assert.strictEqual(truncateSlug('hello-world', 6), 'hello');
});
